#!/usr/bin/env python3
import sqlite3, json

conn = sqlite3.connect('jobs.db')
conn.row_factory = sqlite3.Row
jobs = [dict(r) for r in conn.execute("SELECT * FROM jobs ORDER BY match_score DESC").fetchall()]
conn.close()

total, high, corp, npo = len(jobs), sum(1 for j in jobs if (j.get('match_score') or 0)>=90), sum(1 for j in jobs if j.get('job_type')=='corporate'), sum(1 for j in jobs if j.get('job_type')=='nonprofit')

with open('index.html', 'w') as f:
    f.write(f'''<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Job Dashboard PRO</title><style>*{{margin:0;padding:0;box-sizing:border-box}}body{{font-family:-apple-system,sans-serif;background:linear-gradient(135deg,#667eea,#764ba2);min-height:100vh}}header{{background:#fff;padding:20px 30px;box-shadow:0 4px 12px rgba(0,0,0,.15);position:sticky;top:0;z-index:1000;transition:transform .3s}}header.hidden{{transform:translateY(-100%)}}.header-content{{max-width:1400px;margin:0 auto}}h1{{color:#667eea;font-size:28px;margin-bottom:15px}}.filters{{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:15px}}.filter{{background:#f3f4f6;padding:10px 18px;border-radius:25px;font-size:14px;font-weight:600;cursor:pointer;border:2px solid transparent;transition:all .3s}}.filter:hover{{background:#e5e7eb;transform:translateY(-2px)}}.filter.active{{background:#667eea;color:#fff}}.controls{{display:flex;gap:15px;flex-wrap:wrap}}.search{{flex:1;min-width:250px;padding:12px 20px;border:2px solid #e0e0e0;border-radius:25px;font-size:15px}}.search:focus{{outline:0;border-color:#667eea;box-shadow:0 0 0 3px rgba(102,126,234,.1)}}.tracker-btn{{background:#10b981;color:#fff;padding:12px 24px;border:none;border-radius:25px;font-weight:600;cursor:pointer;text-decoration:none}}.tracker-btn:hover{{background:#059669}}.container{{max-width:1400px;margin:30px auto;padding:0 20px}}.job-card{{background:#fff;border-radius:16px;padding:24px;margin-bottom:20px;box-shadow:0 2px 8px rgba(0,0,0,.1);transition:all .3s;position:relative}}.job-card:hover{{transform:translateY(-4px);box-shadow:0 8px 24px rgba(0,0,0,.15)}}.tags{{position:absolute;top:20px;left:20px;display:flex;gap:8px}}.tag{{padding:6px 14px;border-radius:20px;font-size:12px;font-weight:600;text-transform:uppercase}}.tag.high{{background:#fef3c7;color:#f59e0b}}.tag.corporate{{background:#dbeafe;color:#3b82f6}}.tag.nonprofit{{background:#d1fae5;color:#10b981}}.content{{margin-top:40px}}.title{{font-size:22px;font-weight:700;margin-bottom:12px;color:#1f2937}}.location{{color:#6b7280;margin-bottom:8px}}.company{{color:#2563eb;font-weight:600;margin-bottom:12px}}.summary{{color:#059669;line-height:1.7;margin:15px 0}}.status-row{{margin:15px 0}}.status-dropdown{{padding:8px 16px;border:2px solid #e0e0e0;border-radius:8px;cursor:pointer}}.quick-jumps{{display:flex;gap:10px;flex-wrap:wrap;margin:15px 0}}.quick-jump{{background:#f3f4f6;padding:6px 14px;border-radius:8px;font-size:13px;cursor:pointer;border:none}}.quick-jump:hover{{background:#e5e7eb}}.actions{{display:flex;gap:12px;flex-wrap:wrap;margin-top:20px}}.btn{{flex:1;min-width:140px;padding:14px 20px;border:none;border-radius:12px;font-weight:600;cursor:pointer;color:#fff;box-shadow:0 4px 12px rgba(0,0,0,.15);transition:all .3s}}.btn:hover{{transform:translateY(-3px);box-shadow:0 8px 20px rgba(0,0,0,.25)}}.btn-details{{background:linear-gradient(135deg,#667eea,#764ba2)}}.btn-listing{{background:linear-gradient(135deg,#3b82f6,#2563eb)}}.btn-apply{{background:linear-gradient(135deg,#10b981,#059669)}}.btn-track{{background:linear-gradient(135deg,#f59e0b,#d97706)}}.details{{display:none;margin-top:25px;padding-top:25px;border-top:2px solid #e5e7eb}}.details.show{{display:block}}.section{{margin-bottom:25px}}.section h3{{font-size:18px;margin-bottom:12px;border-bottom:2px solid #667eea;padding-bottom:8px}}.section p{{color:#4b5563;line-height:1.7}}.notes{{margin-top:30px;padding-top:20px;border-top:2px solid #e5e7eb}}.notes-area{{width:100%;min-height:100px;padding:12px;border:2px solid #e0e0e0;border-radius:8px;font-family:inherit;resize:vertical}}.save-notes{{margin-top:10px;padding:10px 20px;background:#667eea;color:#fff;border:none;border-radius:8px;font-weight:600;cursor:pointer}}@media (max-width:768px){{h1{{font-size:22px}}.controls{{flex-direction:column}}.actions{{flex-direction:column}}.btn{{width:100%}}}}</style></head><body><header id="header"><div class="header-content"><h1>📋 Job Search Dashboard PRO</h1><div class="filters"><div class="filter active" onclick="filterJobs('all')">📊 Total: <strong>{total}</strong></div><div class="filter" onclick="filterJobs('high')">🔥 High Match: <strong>{high}</strong></div><div class="filter" onclick="filterJobs('corporate')">🏢 Corporate: <strong>{corp}</strong></div><div class="filter" onclick="filterJobs('nonprofit')">💚 Nonprofit: <strong>{npo}</strong></div></div><div class="controls"><input type="text" class="search" placeholder="🔍 Search jobs..." onkeyup="searchJobs()" id="search"><a href="tracker.html" class="tracker-btn">📋 Job Match Tracker</a></div></div></header><div class="container" id="container"></div><script>const jobs={json.dumps(jobs,default=str)};let currentFilter='all';function renderJobs(){{const container=document.getElementById('container');const searchTerm=document.getElementById('search').value.toLowerCase();let filtered=jobs.filter(job=>{{if(currentFilter==='high'&&(job.match_score||0)<90)return false;if(currentFilter==='corporate'&&job.job_type!=='corporate')return false;if(currentFilter==='nonprofit'&&job.job_type!=='nonprofit')return false;if(searchTerm){{const searchable=[job.title,job.company,job.location,job.brief].join(' ').toLowerCase();if(!searchable.includes(searchTerm))return false;}}return true;}});container.innerHTML=filtered.map(job=>createJobCard(job)).join('');}}function createJobCard(job){{const tags=[];if((job.match_score||0)>=90)tags.push('<span class="tag high">🔥 High Match</span>');tags.push(`<span class="tag ${{job.job_type}}">${{job.job_type}}</span>`);const quickJumps=[];if(job.interview_prep)quickJumps.push('<button class="quick-jump" onclick="jumpTo('+job.id+',\\'interview\\')">Interview Prep</button>');if(job.talking_points)quickJumps.push('<button class="quick-jump" onclick="jumpTo('+job.id+',\\'talking\\')">Talking Points</button>');if(job.red_flags)quickJumps.push('<button class="quick-jump" onclick="jumpTo('+job.id+',\\'red\\')">Red Flags</button>');return`<div class="job-card"><div class="tags">${{tags.join('')}}</div><div class="content"><div class="title">${{job.title||'Untitled'}}</div><div class="location">📍 ${{job.location||'Remote'}}</div><div class="company">${{job.company||'Company'}}</div><div class="summary">${{(job.brief||'No description').substring(0,300)}}...</div><div class="status-row"><label>Status:</label> <select class="status-dropdown" onchange="updateStatus(${{job.id}},this.value)"><option value="New" ${{job.status==='New'?'selected':''}}>New</option><option value="Viewed" ${{job.status==='Viewed'?'selected':''}}>Viewed</option><option value="Applied" ${{job.status==='Applied'?'selected':''}}>Applied</option><option value="Phone Screen">Phone Screen</option><option value="Interview(s) Scheduled">Interview(s) Scheduled</option><option value="Offer Extended">Offer Extended</option><option value="Not a Fit">Not a Fit</option><option value="Not Interested">Not Interested</option></select></div><div class="quick-jumps">${{quickJumps.join('')}}</div><div class="actions"><button class="btn btn-details" onclick="toggleDetails(${{job.id}})">View Job Details →</button><button class="btn btn-listing" onclick="viewListing('${{job.url}}')">View Job Listing</button><button class="btn btn-apply" onclick="applyNow(${{job.id}},'${{job.url}}')">APPLY NOW!</button><button class="btn btn-track" onclick="trackJob(${{job.id}})">Track Match</button></div><div class="details" id="details-${{job.id}}">${{job.company_overview?'<div class="section"><h3>Company Overview</h3><p>'+job.company_overview+'</p></div>':''}}${{job.why_this_role?'<div class="section"><h3>Why This Role</h3><p>'+job.why_this_role+'</p></div>':''}}${{job.interview_prep?'<div class="section" id="section-'+job.id+'-interview"><h3>Interview Prep</h3><p>'+job.interview_prep+'</p></div>':''}}${{job.talking_points?'<div class="section" id="section-'+job.id+'-talking"><h3>Talking Points</h3><p>'+job.talking_points+'</p></div>':''}}${{job.red_flags?'<div class="section" id="section-'+job.id+'-red"><h3>Red Flags</h3><p>'+job.red_flags+'</p></div>':''}}<div class="notes"><h3>📝 Personal Notes</h3><textarea class="notes-area" id="notes-${{job.id}}">${{job.notes||''}}</textarea><button class="save-notes" onclick="saveNotes(${{job.id}})">Save Notes</button></div></div></div></div>`;}}function filterJobs(filter){{currentFilter=filter;document.querySelectorAll('.filter').forEach(f=>f.classList.remove('active'));event.target.classList.add('active');renderJobs();}}function searchJobs(){{renderJobs();}}function toggleDetails(id){{document.getElementById('details-'+id).classList.toggle('show');}}function jumpTo(jobId,section){{document.getElementById('details-'+jobId).classList.add('show');document.getElementById('section-'+jobId+'-'+section).scrollIntoView({{behavior:'smooth'}});}}function viewListing(url){{if(url)window.open(url,'_blank');}}function applyNow(id,url){{updateStatus(id,'Applied');if(url)window.open(url,'_blank');}}function updateStatus(id,status){{console.log('Update job',id,'to status:',status);}}function saveNotes(id){{const notes=document.getElementById('notes-'+id).value;console.log('Save notes for job',id,':',notes);}}function trackJob(id){{window.location.href='tracker.html?job='+id;}}let lastScroll=0;window.addEventListener('scroll',()=>{{const currentScroll=window.pageYOffset;if(currentScroll>lastScroll&&currentScroll>80){{document.getElementById('header').classList.add('hidden');}}else{{document.getElementById('header').classList.remove('hidden');}}lastScroll=currentScroll;}});renderJobs();</script></body></html>''')

print("✅ PRO Dashboard created: index.html")
